-- Align the Storefront table with schema.prisma.
--
-- The storefront_content migration created server-side defaults for columns
-- whose values Prisma always supplies from the application:
--   * "id"        uses @default(uuid())  -> generated by the Prisma client
--   * "updatedAt" uses @updatedAt        -> maintained by the Prisma client
--
-- Every other DoorFlow table stores no default for these columns, so Prisma
-- migrate diff reported a permanent drift for Storefront alone. Dropping the
-- defaults restores a schema that matches schema.prisma; no rows are modified.

ALTER TABLE "Storefront" ALTER COLUMN "id" DROP DEFAULT,
ALTER COLUMN "updatedAt" DROP DEFAULT;
